// Ashby job boards to watch: the slug in jobs.ashbyhq.com/<slug>
// Replace these examples with the companies you want to follow.
const boards = ['ashby', 'linear'];

return boards.map(board => ({ json: { board } }));

// Keep frontend / full-stack / product engineer roles open in Spain, Europe or remote
const boards = $('Companies').all();
const wanted = /front|full[- ]?stack|product engineer/i;
const where = /spain|barcelona|madrid|europe|\beu\b|emea|remote/i;
const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;

const out = [];
$input.all().forEach((item, i) => {
  const company = boards[i]?.json.board;
  for (const job of item.json.jobs || []) {
    const locations = [job.location, ...(job.secondaryLocations || []).map(s => s.location)];
    if (!wanted.test(job.title)) continue;
    if (!locations.some(l => where.test(l || ''))) continue;
    out.push({
      json: {
        company,
        title: job.title,
        locations: locations.filter(Boolean).join(', '),
        url: job.jobUrl,
        published: (job.publishedAt || '').slice(0, 10),
        isNew: Date.parse(job.publishedAt) > weekAgo
      }
    });
  }
});

return out.sort((a, b) => b.json.published.localeCompare(a.json.published));
